const results = [];
var output = {};

for (const item of $('Analyze table 2-4').all()) {
  try {
    // 1. ดึงข้อความดิบ
    let rawText = item.json.candidates[0].content.parts[0].text;

    // 2. ใช้ Regex ดึงเฉพาะเนื้อหาที่อยู่ระหว่าง ```json และ ```
    // [\s\S]*? คือการจับทุกตัวอักษร (รวมขึ้นบรรทัดใหม่) แบบ non-greedy
    const regex = /```json\s*([\s\S]*?)\s*```/i;
    const match = rawText.match(regex);

    let cleanText = "";
    if (match && match[1]) {
      // ถ้าเจอ block ```json ให้เอาเนื้อหาข้างในมาใช้
      cleanText = match[1].trim();
    } else {
      // ถ้าไม่เจอ block ให้ลองใช้ข้อความดิบทั้งหมด (เผื่อ AI ไม่ได้ใส่ code block มา)
      cleanText = rawText.trim().replace(/^```(json)?/i, '').replace(/```$/i, '').trim();
    }

    // 3. แปลงเป็น JSON
    let parsedData = JSON.parse(cleanText);

    // 4. จัดรูปแบบข้อมูลให้เป็น n8n Item (Array of Objects)
    if (Array.isArray(parsedData)) {
      for (const row of parsedData) {
        results.push({ json: (typeof row === 'object' && row !== null) ? row : { value: row } });
      }
    } else if (typeof parsedData === 'object' && parsedData !== null) {
      // ตรวจสอบเคสพิเศษ: ถ้ามี key "output" อยู่ข้างใน (ตามตัวอย่างที่คุณส่งมา)
      // เราจะดึงข้อมูลใน "output" ออกมาเป็นแถวๆ แทนที่จะส่งก้อนใหญ่ก้อนเดียว
      if (parsedData.output && Array.isArray(parsedData.output)) {
        for (const row of parsedData.output) {
          results.push({ json: row });
        }
      } else {
        // กรณีเป็น Object ทั่วไปที่ไม่มีคีย์ output
        for (const key in parsedData) {
          let row = parsedData[key];
          if (typeof row === 'object' && row !== null && !Array.isArray(row)) {
            if (!row.row_id) row.row_id = key;
            results.push({ json: row });
          } else {
            results.push({ json: { row_id: key, value: row } });
          }
        }
      }
    } else {
      results.push({ json: { result: parsedData } });
    }

  } catch (error) {
    results.push({ json: { error: "Failed to parse JSON", details: error.message } });
  }
}

output = {
  "tb": "tb_4/4",
  "result": results
};

return output;

