        // ถ้ายังไม่มีหมายเลขแถวนี้ ให้สร้าง Object ใหม่รอไว้
        if (!mergedRows[rowNum]) {
          mergedRows[rowNum] = { row: rowNum };
        }

        // วนลูปดึงข้อมูลคอลัมน์ A, B, C... มาใส่
        if (rowData.response) {
          for (const [key, value] of Object.entries(rowData.response)) {

            let cleanValue = value;

            // ดักจับข้อความคำว่า "null", "Null", "NULL" หรือมีเว้นวรรคติดมา
            if ((typeof cleanValue === 'string' && cleanValue.trim().toLowerCase() === 'null') || (typeof cleanValue === 'string' && cleanValue.trim().toLowerCase() === '-') || (typeof cleanValue === 'string' && cleanValue.trim().toLowerCase() === '0')) {
              cleanValue = null; // แปลงให้เป็นค่า null จริงๆ
            }

            // ใช้ tableIndex + 1 (T1, T2, T3, T4) เพื่อไม่ให้ชื่อคอลัมน์ชนกัน
            mergedRows[rowNum][`T${tableIndex + 1}_${key}`] = cleanValue;
          }
        }
      }
    });
  }
});

