function getOrientation(buf){
  if(buf[0]!==0xFF||buf[1]!==0xD8) return 1;
  let off=2;
  while(off < buf.length){
    if(buf[off]!==0xFF){off++;continue;}
    const m=buf[off+1];
    if(m===0xE1){
      const segLen=buf.readUInt16BE(off+2);
      if(buf.toString('ascii',off+4,off+8)==='Exif'){
        const tiff=off+10;
        const le=buf.toString('ascii',tiff,tiff+2)==='II';
        const r16=o=>le?buf.readUInt16LE(o):buf.readUInt16BE(o);
        const r32=o=>le?buf.readUInt32LE(o):buf.readUInt32BE(o);
        const dir=tiff+r32(tiff+4);
        const n=r16(dir);
        for(let i=0;i<n;i++){
          const e=dir+2+i*12;
          if(r16(e)===0x0112) return r16(e+8);
        }
      }
      off+=2+segLen;
    } else if(m===0xD9||m===0xDA){break;}
    else { off+=2+buf.readUInt16BE(off+2); }
  }
  return 1;
}

