const GROUP_ID    = "C4405f7c3184ce0d5d750895395488612";
// === Node: build-report-text ===

const rows = $input.all().map(i => i.json);

// filter วันที่ที่ node Get sheet แล้ว → ไม่ต้อง filter ที่นี่
const filtered = rows;

function fmtTime(t) {
  if (t == null) return '';
  const parts = String(t).split(':');
  const hhmm = parts.slice(0, 2).join('.');
  return hhmm.replace(/^0/, '');
}

function shortName(name) {
  if (name == null) return '-';
  return String(name).split('|')[0].trim();
}

function machineSortKey(m) {
  if (m == null) return Infinity;
  const after = String(m).split('/')[1];
  const n = parseInt(after, 10);
  return isNaN(n) ? Infinity : n;
}

// group: วันที่ -> (เครื่อง + สินค้า) -> ประเภทของเสีย -> Set(เวลา)
const byDate = {};
filtered.forEach(r => {
  const date = r.production_date || '-';
  const key = `${r.machine_no || '-'}__${r.product_name || '-'}`;
  byDate[date] = byDate[date] || {};
  byDate[date][key] = byDate[date][key] || {
    machine_no: r.machine_no, product_name: r.product_name, defects: {},
  };
  if (r.defect_name && r.inspect_time != null) {
    const b = byDate[date][key];
    (b.defects[r.defect_name] = b.defects[r.defect_name] || new Set()).add(fmtTime(r.inspect_time));
  }
});

// สร้างข้อความแต่ละวัน แล้วรวมเป็นข้อความเดียว
const blocksText = [];
Object.keys(byDate).forEach(date => {
  const lines = [`รายงานตรวจสอบ DQM-002+004 (${date})`];
  const blocks = Object.values(byDate[date]).sort(
    (a, b) => machineSortKey(a.machine_no) - machineSortKey(b.machine_no)
  );
  let idx = 1;
  blocks.forEach(block => {
    lines.push(`${idx}. ${block.machine_no} ${shortName(block.product_name)}`);
    const names = Object.keys(block.defects);
    if (names.length === 0) {
      lines.push(`   • ไม่พบปัญหา Critical`);
    } else {
      names.forEach(dn => lines.push(`   - พบ${dn}: ${[...block.defects[dn]].join(', ')}`));
    }
    idx++;
  });
  blocksText.push(lines.join('\n'));
});

const msg = blocksText.join('\n\n');

return [{
  json: {
    to: GROUP_ID,
    messages: [{ type: "text", text: msg.trim() }]
  }
}];

