function fmtTime(t) {
  if (t == null || String(t).trim() === '') return null;
  return String(t).split(':').slice(0, 2).join(':');
}

function cell(rows, rowNum, col) {
  const r = rows.find(x => x.row === rowNum);
  return r && r.response ? (r.response[col] ?? null) : null;
}
const meta = {
  production_date:  cell(node1, 1, 'B'),
  machine_no:       cell(node1, 2, 'D'),
  product_name:     cell(node1, 3, 'B'),
  production_shift: cell(node1, 3, 'D'),
  product_code:     cell(node1, 4, 'B'),
};

const defectCols = [];
node2.forEach(r => {
  const name = r.response ? r.response.A : null;
  if (name != null && String(name).trim() !== '') {
    const colLetter = String.fromCharCode(65 + r.row); // row1 -> 'B'
    const raw = String(name).trim();
    const parts = raw.split('|').map(s => s.trim());
    defectCols.push({
      col: colLetter,
      code: parts.length > 1 ? parts[0] : null,
      name: parts.length > 1 ? parts[1] : raw,
      label: raw,
    });
  }
});

