      if (rd && rd.row && rd.response) dataRows.push({ row: rd.row, response: rd.response });
    });
  }
});

const out = [];
dataRows.forEach(dr => {
  const inspectTime = fmtTime(dr.response.A);   // ตัดเหลือ hh:mm
  defectCols.forEach(dc => {
    const rawQty = dr.response[dc.col];
    const qty = (rawQty == null || String(rawQty).trim() === '') ? null : Number(rawQty);
    if (qty != null && !isNaN(qty) && qty !== 0) {
      out.push({
        production_date: meta.production_date ?? null,
        machine_no: meta.machine_no ?? null,
        product_name: meta.product_name ?? null,
